    // -------------------------------------------------------------------------
    // Signal gantries
    // -------------------------------------------------------------------------

    function createSignal(x, z, y, facing, label, route) {
      const group = new THREE.Group();
      group.position.set(x, y, z);
      world.add(group);

      const redMat = new THREE.MeshStandardMaterial({
        color: 0xff3344,
