      );
      amber.rotation.z = Math.PI / 2;
      amber.position.set(0.68, 2.02, 0);
      group.add(amber);

      const green = new THREE.Mesh(
        new THREE.CylinderGeometry(0.19, 0.19, 0.14, 20),
