      );
      label.rotation.y = facing > 0 ? Math.PI / 2 : -Math.PI / 2;
      label.position.set(0.3, 3.15, 0);
      group.add(label);

      return {
        redMat,
        amberMat,
        greenMat,
        labelMaterial,
        label
      };
    }

    function applySignal(signal, state) {
      const red = state === "red";
      const amber = state === "amber";
      const green = state === "green";

      signal.redMat.visible = red;
      signal.amberMat.visible = amber;
      signal.greenMat.visible = green;

      signal.redMat.emissiveIntensity = red ? 2.4 : 0;
      signal.amberMat.emissiveIntensity = amber ? 2.4 : 0;
      signal.greenMat.emissiveIntensity = green ? 2.4 : 0;
    }

    const westMainSignal = createSignal(
      -58, -6.6, platformTop, -1, "J1", "MAIN"
    );

    const eastMainSignal = createSignal(
      58, 6.6, platformTop, 1, "J2", "MAIN"
    );

    const westJunctionSignal = createSignal(
      -51, -16, platformTop, -1, "J1", "J1"
    );

    const eastJunctionSignal = createSignal(
      51, 16, platformTop, 1, "J2", "J2"
    );

    // -------------------------------------------------------------------------
    // Trains
    // -------------------------------------------------------------------------

    function createTrain(color, label) {
      const group = new THREE.Group();
      world.add(group);

      const bodyMat = material(color, 0.38, 0.3);
      const accentMat = material(0xf4f7f4, 0.4, 0.25);

      function car(x) {
        const car = new THREE.Group();
        car.position.x = x;
        group.add(car);

        box(9.2, 2.2, 2.65, bodyMat, 0, 1.25, 0, car);
        box(8.35, 0.24, 2.35, accentMat, 0, 2.43, 0, car);

        for (const side of [-1, 1]) {
          for (const dx of [-3.1, -1.6, 0, 1.6, 3.1]) {
            box(
              1.25,
              0.78,
              0.065,
              M.glass,
              dx,
              1.68,
              side * 1.34,
              car
            );
          }

          box(
            8.4,
            0.18,
            0.065,
            accentMat,
            0,
            1.05,
            side * 1.35,
            car
          );
        }

        [-3.15, 3.15].forEach((wheelX) => {
          [-1.35, 1.35].forEach((wheelZ) => {
            const wheel = new THREE.Mesh(
              new THREE.CylinderGeometry(0.3, 0.3, 0.18, 16),
              M.steel
            );
            wheel.rotation.x = Math.PI / 2;
            wheel.position.set(wheelX, 0.3, wheelZ);
            car.add(wheel);
          });
        });

        box(0.7, 0.35, 0.45, M.steel, 4.7, 1.0, 0, car);
      }

      function locomotive() {
        const loco = new THREE.Group();
        group.add(loco);

        box(7.2, 2.45, 2.7, bodyMat, 0, 1.35, 0, loco);
        box(2.15, 2.5, 2.7, bodyMat, 2.75, 1.4, 0, loco);
        box(2.35, 0.25, 2.9, accentMat, 2.75, 2.72, 0, loco);

        box(1.75, 0.85, 0.08, M.glass, 3.94, 1.95, 0, loco);

        for (const side of [-1, 1]) {
          box(
            1.65,
            0.8,
            0.06,
            M.glass,
            2.75,
            1.95,
            side * 1.37,
            loco
          );
        }

        [-3.15, 3.15].forEach((wheelX) => {
          [-1.35, 1.35].forEach((wheelZ) => {
            const wheel = new THREE.Mesh(
              new THREE.CylinderGeometry(0.34, 0.34, 0.2, 16),
              M.steel
            );
            wheel.rotation.x = Math.PI / 2;
            wheel.position.set(wheelX, 0.34, wheelZ);
            loco.add(wheel);
          });
