      }
    ].map((spec) => createTrain(spec.color, spec.label));

    // -------------------------------------------------------------------------
    // Street vehicles
    // -------------------------------------------------------------------------

    function createCar(color, horizontal = true) {
      const group = new THREE.Group();
      world.add(group);

      const bodyMat = material(color, 0.4, 0.25);

      box(4.1, 0.9, 1.8, bodyMat, 0, 0.7, 0, group);
      box(2.4, 0.65, 1.55, M.glass, -0.25, 1.35, 0, group);
