    const roadCars = [];

    function addRoadCar(x, z, speed, direction, color) {
      const car = createCar(color);
      roadCars.push({
        group: car,
        update() {
          const length = 260;
          const travel = ((simTime * speed + x) % length) + z;
          car.position.set(
            horizontal ? -130 + travel : x,
            0.25,
            horizontal ? z : -130 + travel
          );

          if (horizontal) {
            car.rotation.y = 0;
          } else {
            car.rotation.y = direction > 0 ? -Math.PI / 2 : Math.PI / 2;
          }
        }
      });
    }

    addRoadCar(-55, -42, 8, 1, 0xa94f43);
    addRoadCar(30, 42, 9, -1, 0x426f9c);
    addRoadCar(-78, 0, 7, 1, 0x3b8e70);
    addRoadCar(78, 0, 8, -1, 0xe0ad3c);
    addRoadCar(-30, -42, 6, 1, 0x647d91);
    addRoadCar(30, 42, 7, -1, 0x8a5b4b);

    // -------------------------------------------------------------------------
    // Signal and train animation
    // -------------------------------------------------------------------------

    const westTrain = trainSpecs[2];
    const eastTrain = trainSpecs[3];
    const westMainTrain = trainSpecs[0];
    const eastMainTrain = trainSpecs[1];

    function signalStateFor(spec, train) {
      if (spec.route === "J1") {
        if (train.progress < 0.08) return "red";
        if (train.progress < 0.42) return "amber";
        return "green";
      }

      if (train.progress < 0.22) return "red";
      if (train.progress < 0.55) return "amber";
      return "green";
    }

    function updateSignals() {
      applySignal(
        westJunctionSignal,
        signalStateFor(westJunctionSignal, westTrain)
      );
      applySignal(
        eastJunctionSignal,
        signalStateFor(eastJunctionSignal, eastTrain)
      );
      applySignal(
        westMainSignal,
        signalStateFor(westMainSignal, westMainTrain)
      );
      applySignal(
        eastMainSignal,
        signalStateFor(eastMainSignal, eastMainTrain)
      );
    }

    // -------------------------------------------------------------------------
    // Direct camera controls: orbit, pan, zoom
    // -------------------------------------------------------------------------

    const cameraView = {
      target: new THREE.Vector3(0, 12, 0),
      radius: 225,
      theta: 0.72,
      phi: 0.92
    };

    function updateCamera() {
      const sinPhi = Math.sin(cameraView.phi);

      camera.position.set(
        cameraView.target.x +
          cameraView.radius * sinPhi * Math.sin(cameraView.theta),
        cameraView.target.y +
          cameraView.radius * Math.cos(cameraView.phi),
        cameraView.target.z +
          cameraView.radius * sinPhi * Math.cos(cameraView.theta)
      );

      camera.lookAt(cameraView.target);
      camera.updateMatrixWorld();
    }

    function resetView() {
      cameraView.target.set(0, 12, 0);
      cameraView.radius = 225;
      cameraView.theta = 0.72;
      cameraView.phi = 0.92;
      updateCamera();
    }

    const viewButtons = [...document.querySelectorAll("[data-view]")];

    viewButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const view = button.dataset.view;

        if (view === "overview") {
          cameraView.target.set(0, 12, 0);
          cameraView.radius = 225;
          cameraView.theta = 0.72;
          cameraView.phi = 0.92;
        } else if (view === "station") {
          cameraView.target.set(0, 8, 0);
          cameraView.radius = 125;
          cameraView.theta = 0.66;
          cameraView.phi = 0.9;
        } else if (view === "junction") {
          cameraView.target.set(-45, 9, 0);
          cameraView.radius = 92;
          cameraView.theta = 0.8;
          cameraView.phi = 1.0;
        }

        updateCamera();
      });
    });

    const pointer = {
      active: false,
      mode: "orbit",
      x: 0,
      y: 0
    };

    renderer.domElement.addEventListener("contextmenu", (event) => {
      event.preventDefault();
    });

    renderer.domElement.addEventListener("pointerdown", (event) => {
      pointer.active = true;
      pointer.mode = event.button === 2 ? "pan" : "orbit";
      pointer.x = event.clientX;
      pointer.y = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!pointer.active) return;

      const dx = event.clientX - pointer.x;
      const dy = event.clientY - pointer.y;
      pointer.x = event.clientX;
      pointer.y = event.clientY;

      if (pointer.mode === "orbit") {
        cameraView.theta -= dx * 0.005;
        cameraView.phi = THREE.MathUtils.clamp(
          cameraView.phi - dy * 0.005,
          0.25,
          1.45
        );
      } else {
        const right = new THREE.Vector3().setFromMatrixColumn(
          camera.matrix,
          0
        );
        const up = new THREE.Vector3().setFromMatrixColumn(
          camera.matrix,
          1
        );

        cameraView.target
          .addScaledVector(right, -dx * cameraView.radius * 0.0013)
          .addScaledVector(up, dy * cameraView.radius * 0.0013);
      }

      updateCamera();
    });

    function endPointer(event) {
      pointer.active = false;
      if (renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endPointer);
    renderer.domElement.addEventListener("pointercancel", endPointer);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraView.radius = THREE.MathUtils.clamp(
          cameraView.radius * Math.exp(event.deltaY * 0.001),
          70,
          340
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetView);

    // -------------------------------------------------------------------------
    // UI and animation loop
    // -------------------------------------------------------------------------

    let paused = false;
    const pauseButton = document.getElementById("pause");
    const loading = document.getElementById("loading");

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
    });

    const clock = new THREE.Clock();
    let simulationTime = 0;

    function animate() {
      const dt = Math.min(clock.getDelta(), 0.05);

      if (!paused) {
        simulationTime += dt;
      }

      // Trains follow their respective track curves.
      trainSpecs.forEach((spec, index) => {
        const train = trainSpecs[index];
        const length = train.curve.getLength();
        const u = ((train.progress + simulationTime * train.speed / length) % 1 +
          1) % 1;

        const point = train.curve.getPointAt(u);
        const tangent = train.curve.getTangentAt(u);

        train.group.position.copy(point);
        train.group.position.y += Math.sin(simulationTime * 2 + index) * 0.015;
        train.group.rotation.y = -Math.atan2(tangent.z, tangent.x);

        train.sprite.position.copy(point);
        train.sprite.position.y += 5.2;
      });

      roadCars.forEach((car) => car.update());

      updateSignals();

      // Gentle pedestrian movement on the platform.
      const people = [
        person(-31, 2.8, 0xe26b4f),
        person(-28.5, 3.1, 0x3c7895),
        person(24, -2.8, 0xd6a84a),
        person(27, -3.1, 0x4c7858),
        person(8, 4.9, 0x8c5aa4)
      ];

      people.forEach((person, index) => {
        const leg = person.userData.legL || person.userData.legR;
        leg.rotation.x = Math.sin(simulationTime * 2.1 + index) * 0.25;
      });

      renderer.render(scene, camera);
    }

    addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    });

    resetView();
    renderer.setAnimationLoop(animate);

    window.setTimeout(() => {
      loading.classList.add("hidden");
      window.setTimeout(() => loading.remove(), 600);
    }, 300);
  </script>
